    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "In this paper, we reviewed the literature assessing the quality of ecological meta-analyses, collected new data to evaluate current practices, and highlight the areas that need more work. First, we compiled information from 18 studies in the last 20 years (between 2002 and 2022) that reviewed the quality of meta-analyses in ecology, evolution and related fields.",
      "reason": "Identifies and cites previous similar systematic reviews, explaining the need for the current review to compile and synthesize data from multiple reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a meta-evaluation of the quality of reporting and execution in ecological meta-analyses, not a review of intervention effects, so this element does not apply."
    },
